#!/usr/bin/env bash
# GSZ step125 — future-proof bot submit payload: explicit top-level email +
# deliveryType for all product types (vendor_invite/amember/portal/future).
# Safe + idempotent; restores on failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step125-$TS"; TMP=$(mktemp -d)
F=routes/checkout.js
echo "==> step125: future-proof bot submit payload"
mkdir -p "$BK/$(dirname "$F")"; cp "$GSZ/$F" "$BK/$F"; echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; cp "$BK/$F" "$GSZ/$F"; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"; node --check "$GSZ/$F"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step125 OK ✅  Website now sends email + deliveryType with every bot order (single + cart), for any product type now or future."
